INSERT INTO [dbo].[seminars] ([seminar_id], [TitleHtml], [EventDetailsHtml], [Description], [StartDate], [Enddate], [Address1], [Address2], [City], [StateProvince], [ZipPostalCode], [Country], [Email], [Phone], [Fax], [ContactEmail], [ContactPhone], [ContactWebsite], [IsActive], [Starttime], [Endtime], [instructor_id]) VALUES (3, N'Advanced Regression Analysis', N'<p>This workshop provides reporting basics for accounting employees new to unclaimed property or anyone who would like to refresh their knowledge of this specialized area. Topics include:</p>  <ul style="list-style-type:disc;margin-left:20px;"><li>History of unclaimed property</li><li>Purpose and benefits of the Act</li><li>Common property types</li><li>Dormancy periods</li><li>Due diligence requirements and tips</li><li>Preparing your report &ndash; when, where, and how</li><li>Common reporting and remitting errors</li><li>Electronic reporting</li><li>Developing an effective unclaimed property accounting system</li></ul>', N'This  workshop provides reporting basics for accounting employees new to unclaimed property or anyone who would like to refresh their knowledge of this specialized area.', N'2015-06-06 00:00:00', N'2015-06-08 00:00:00', N'west side', NULL, N'chicago', N'IL', NULL, N'Nigeria', N'test@anc.com', NULL, NULL, NULL, NULL, NULL, 0, NULL, NULL, NULL)
INSERT INTO [dbo].[seminars] ([seminar_id], [TitleHtml], [EventDetailsHtml], [Description], [StartDate], [Enddate], [Address1], [Address2], [City], [StateProvince], [ZipPostalCode], [Country], [Email], [Phone], [Fax], [ContactEmail], [ContactPhone], [ContactWebsite], [IsActive], [Starttime], [Endtime], [instructor_id]) VALUES (5, N'Unclaimed Property for Financial Institutions', N'<p>This free workshop covers subjects of interest to the  banking community such as:</p> <ul style="list-style-type:disc;margin-left:20px;"><li>Property types and issues unique to financial  institutions</li><li>Aging and controlling inactive customer accounts</li><li>Inactivity charges and ceasing interest</li><li>Time Certificates, IRAs, Keoghs and Special  Designation Accounts</li>      <li>Positive owner contact and notifying owners of  account changes</li><li>Abandoned safe deposit boxes</li><li>Audit process</li></ul><p><strong>Important:&nbsp; We will not cover basic reporting information  in this workshop.&nbsp; Sign up for a Basics  101 workshop if you need this information.</strong></p>', N'This free workshop covers subjects of interest to the  banking community', N'2015-06-15 00:00:00', N'2015-06-18 00:00:00', N'Streat 1', NULL, NULL, N'IL', NULL, N'United States', N'test@mmmm.com', NULL, NULL, NULL, NULL, NULL, 0, NULL, NULL, NULL)
INSERT INTO [dbo].[seminars] ([seminar_id], [TitleHtml], [EventDetailsHtml], [Description], [StartDate], [Enddate], [Address1], [Address2], [City], [StateProvince], [ZipPostalCode], [Country], [Email], [Phone], [Fax], [ContactEmail], [ContactPhone], [ContactWebsite], [IsActive], [Starttime], [Endtime], [instructor_id]) VALUES (7, N'test seminar', N'&lt;p&gt;test sample&lt;/p&gt;&lt;ul&gt;&lt;li&gt;test1&lt;/li&gt;&lt;li&gt;test2&lt;/li&gt;&lt;li&gt;test3&lt;/li&gt;&lt;/ul&gt;', N'test seminar 1', N'2015-04-20 00:00:00', N'2015-04-21 00:00:00', N'lkjhgfds', N'lkjhgfd', N'lkjhgfds', N'kmjhgfdsa', NULL, N'United States', N'ytre@uytre.com', N'7654321', NULL, N'twee@teww.com', NULL, N'www.axcm.com', 0, NULL, NULL, NULL)
INSERT INTO [dbo].[seminars] ([seminar_id], [TitleHtml], [EventDetailsHtml], [Description], [StartDate], [Enddate], [Address1], [Address2], [City], [StateProvince], [ZipPostalCode], [Country], [Email], [Phone], [Fax], [ContactEmail], [ContactPhone], [ContactWebsite], [IsActive], [Starttime], [Endtime], [instructor_id]) VALUES (9, N'Regression Analysis', N'<ul style="margin-right: 0px;" dir="ltr"><ul dir="ltr"><li><p align="left" style="margin-right: 0px;">The relationships between two or more variables are often modeled with a linear regression. Linear regression gives the basis of modeling data in Statistics. It is the most widely used statistical technique for both experimental and non-experimental data. The theories of logistic regression, survival analysis etc. are rooted in the foundations gained in linear regression. It is therefore the most basic methodological technique to the analysis of statistical Data and a must for all researchers.This subject has seen several changes over the decades and this seminar will expose participants to recent developments in regression analysis such as: new diagnostic tools, non-linear regression techniques and Lasso.<br><br>Participants who have had this course a while back or who have never had a course on this topic will all benefit immensely from the instructional style for this course. <br><br>The course will be taught from the instructor’s joint authorship book ‘Applied Statistics: Regression and Analysis of Variance by Lawal and Famoye (2013)- UPA, Lanham,&nbsp; PA. USA.<br><br style="margin-right: 0px;">Topics include:<br style="margin-right: 0px;">•&nbsp;History of unclaimed property<br style="margin-right: 0px;">•&nbsp;Purpose and benefits of the Act<br style="margin-right: 0px;">•&nbsp;Common property types<br style="margin-right: 0px;">•&nbsp;Dormancy periods<br style="margin-right: 0px;">•&nbsp;Due diligence requirements and tips<br style="margin-right: 0px;">•&nbsp;Preparing your report – when, where, and how<br style="margin-right: 0px;">•&nbsp;Common reporting and remitting errors<br style="margin-right: 0px;">•&nbsp;Electronic reporting<br style="margin-right: 0px;">•&nbsp;Developing an effective unclaimed property accounting system<br style="margin-right: 0px;"><br><b>STATISTICAL PACKAGE:</b><br>The workshop will employ bot R and Stata packages for analysis. Participants should therefore bring their laptops as there would be a lot of hands-on exercises. The package R will be loaded by our staff for each participants.<I>The Stata package is available from StataCorp, College Station, Texas, USA (<a href="www.stata.com">www.stat.com</a>). The company is currently shipping Stata 14 and participants can take advantage of their 30-day software return policy. We are currently working with stataCorp on this deal.</I><br><br>WHO SHOULD ATTEND<br>The workshop is designed for people with a basic understanding in Statistics and those that wish to understand more on recent advances and computer applications in linear regression analysis. Good for researchers in social sciences, medicine and bio-sciences and for academic instructors in the nation’s polytechnics and universities.<br>The course will be non-mathematical but a good understanding of mathematics will be assumed.</p><p align="left" style="margin-right: 0px;"><br><b>LOCATION and TIME:</b><br>The workshop meets<b> 9 a.m – 4 p.m Monday to Wednesday</b> <i>(with one hour for lunch)</i> at the ball room of Princess Hotel, along Pipeline Road, Ilorin, Kwara State.</p><p align="left" style="margin-right: 0px;"><br><b>REGISTRATION</b><br>The fee for the course is N120,000.00 per participant and includes all workshop materials. The early registration fee of N100,000.00 is available before May 25.</p></li><li><p align="left" style="margin-right: 0px;">&nbsp;</p></li><li><p align="left" style="margin-right: 0px;"><b>LODGING</b></p><li><p align="left" style="margin-right: 0px;">1.Princess Luxury Hotel<br>Plot 31, Pipeline Road<br>Ilorin. Kwara State<br>Tel #: 09032499226<br>e-mail:<a href="mailto:info@princessluxuryhotels.com">info@princessluxuryhotels.com</a></p></li><li><p align="left" style="margin-right: 0px;">2.Kwara Hotel<br>No 9A Ahmadu Bello Way<br>Ilorin. Kwara State<br>Tel #:08147118621</p></li><li><p align="left" style="margin-right: 0px;">3.Kingstone Grand Suites<br>7, Ahman Patigi Road<br>GRA. Ilorin. Kwara State<br>Tel #: 07031184505<br>08076553519<br>e-mail: <a href="mailto:kingstonehotels@yahoo.com">kingstonehotels@yahoo.com</a></p></li></ul></ul>', N'This  workshop provides reporting basics for accounting employees new to unclaimed property or anyone who would like to refresh their knowledge of this specialized area.', N'2015-06-01 00:00:00', N'2015-06-03 00:00:00', N'west side', NULL, N'chicago', N'IL', NULL, N'Nigeria', N'test@anc.com', NULL, NULL, NULL, NULL, NULL, 1, N'9AM', N'4PM', NULL)
